practice.solution:
def dora(deploys, failed, days, lead_hours):
    per_week = round(deploys / days * 7, 2)
    pct = round(failed / deploys * 100, 1) if deploys else 0.0
    s = sorted(lead_hours)
    n = len(s)
    if n == 0:
        med = 0
    elif n % 2 == 1:
        med = s[n // 2]
    else:
        med = (s[n // 2 - 1] + s[n // 2]) / 2
    return [per_week, pct, med]

def stage_order(stages):
    deps = {}
    for name, d in stages:
        deps[name] = list(d)
    done = []
    while len(done) < len(deps):
        ready = []
        for n in deps:
            if n not in done:
                ok = True
                for d in deps[n]:
                    if d not in done:
                        ok = False
                if ok:
                    ready.append(n)
        ready.sort()
        done.append(ready[0])
    return done

