def bump(version, part):
    a, b, c = [int(x) for x in version.split('.')]
    if part == 'major':
        a += 1
        b = 0
        c = 0
    elif part == 'minor':
        b += 1
        c = 0
    else:
        c += 1
    return str(a) + '.' + str(b) + '.' + str(c)

