    pass

practice.solution:
def plan(want, have):
    out = []
    for k in want:
        if k not in have:
            out.append('+ ' + k)
        elif want[k] != have[k]:
            out.append('~ ' + k)
    for k in have:
        if k not in want:
            out.append('- ' + k)
    return sorted(out)

