practice.solution:
def canary(new_requests, new_errors, base_requests, base_errors, margin):
    if new_requests < 100:
        return 'wait'
    new_rate = new_errors / new_requests
    base_rate = base_errors / base_requests if base_requests else 0.0
    if new_rate <= base_rate + margin:
        return 'promote'
    return 'rollback'

