    # your code
    pass

practice.solution:
def percentile(values, p):
    if not values:
        return 0
    s = sorted(values)
    n = len(s)
    r = p * n / 100
    k = int(r)
    if k < r:
        k += 1
    if k < 1:
        k = 1
    return s[k - 1]

