practice.solution:
def ver(s):
    return [int(x) for x in s.split('.')]


def vulnerable(deps, advisories):
    limit = {}
    for a in advisories:
        name, v = a.split('<')
        limit[name] = ver(v)
    out = []
    for d in deps:
        name, v = d.split('==')
        if name in limit and ver(v) < limit[name]:
            out.append(name)
    return sorted(out)
